function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var levels := new List<integer>;
  var level := 0;

  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = '(' then
    begin
      level += 1;
      stack.Push(level);
      levels.Add(level);
    end
    else if parenString[i] = ')' then
    begin
      level -= 1;
      var maxLevel := stack.Peek;
      stack.Pop;
      levels[levels.Count - 1] := maxLevel;
    end;
  end;

  Result := levels.ToArray;
end;


