function MakePalindrome(str1: string): string;
begin
  var n := str1.Length;
  if n = 0 then
  begin
    Result := '';
    exit;
  end;

  var postfix := '';
  for var i := n - 1 downto 0 do
  begin
    var suffix := str1.Substring(i);
    if IsPalindrome(suffix) then
    begin
      postfix := suffix;
      break;
    end;
  end;

  if postfix = '' then
    Result := str1
  else
  begin
    var prefix := str1.Substring(0, n - postfix.Length);
    var suffixReverse := ReverseString(postfix);
    Result := str1 + prefix + suffixReverse;
  end;
end;


