function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var factors := new List<integer>;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      num := num div i;
      factors.Add(i);
    end
    else
      i += 1;
  end;

  if num > 1 then
    factors.Add(num);

  var res := new List<integer>;
  var counts := new Dictionary<integer, integer>;

  foreach var f in factors do
  begin
    if not counts.ContainsKey(f) then
      counts[f] := 0;
    counts[f] += 1;
  end;

  foreach var kv in counts do
    res.Add(kv.Value);

  Result := res.ToArray;
end;


