function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n mod 2 <> 0 then
    raise new System.ArgumentException('xs must have even number of coefficients');
  var maxCoeff := xs.Max;
  if maxCoeff = 0 then
  begin
    Result := 0;
    exit;
  end;
  var (a, b) := (xs[0], xs[1]);
  for var i := 2 to n - 1 step 2 do
  begin
    var coeff := xs[i];
    var pow := i mod 4 + 2;
    a := a * coeff + b * Power(x, pow);
    b := coeff;
  end;
  Result := a / b;
end;


