function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n = 0 then
  begin
    Result := new real[0];
    exit;
  end;
  if n = 1 then
  begin
    Result := new real[0];
    exit;
  end;
  var res := new real[n - 1];
  for var i := 1 to n - 1 do
    res[i - 1] := (i) * xs[i];
  Result := res;
end;


