    for var j := 2 to Trunc(Sqrt(i)) do
      if i mod j = 0 then
      begin
        isPrime := False;
        break;
      end;
    if isPrime then
      primes.Add(i);
    i += 1;
  end;

  var primeCount := 0;
  var composite := False;
  for var p := 0 to primes.Count - 1 do
  begin
    if a mod primes[p] = 0 then
      primeCount += 1
    else
      composite := True;
  end;

  Result := composite and (primeCount = 3);
end;


