function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aDigit := 0;
  var bDigit := 0;
  var aPos := 0;
  var bPos := 0;

  while a > 0 do
  begin
    aDigit := a mod 10;
    a := a div 10;

    while b > 0 do
    begin
      bDigit := b mod 10;
      b := b div 10;

      product := product + (aDigit * bDigit * (10 ** (10 - aPos - bPos - 1)));
      aPos += 1;
    end;
    bPos += 1;
  end;

  Result := product;
end;


