function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;

  for var i := 1 to n do
  begin
    var isPalindrome := True;
    var num := i;

    while num > 0 do
    begin
      var lastDigit := num mod 10;
      var reversed := (num div 10);

      if lastDigit <> reversed then
      begin
        isPalindrome := False;
        break;
      end;

      num := reversed;
    end;

    if i mod 2 = 0 then
      if isPalindrome then
        evenCount += 1
      else
        oddCount += 1
    else
      if isPalindrome then
        oddCount += 1
      else
        evenCount += 1;
  end;

  Result := (evenCount, oddCount);
end;


