function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var count := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
      begin
        buckets[i, j] := 1;
        count += 1;
      end;

  var total := count;
  var filled := m * n;

  while (total <> filled) and (count <> capacity) do
  begin
    var newCount := 0;

    for var i := 0 to m - 1 do
      for var j := 0 to n - 1 do
        if buckets[i, j] = 1 then
        begin
          if (i > 0) and (buckets[i-1, j] = 0) then
            newCount += 1;
          if (i < m - 1) and (buckets[i+1, j] = 0) then
            newCount += 1;
          if (j > 0) and (buckets[i, j-1] = 0) then
            newCount += 1;
          if (j < n - 1) and (buckets[i, j+1] = 0) then
            newCount += 1;

          buckets[i, j] := 0;
          count -= 1;
        end;

    if newCount <> count then
    begin
      count := newCount;
      total := total + newCount;
    end;
  end;

  Result := count;
end;


