function MatchParens(lst: array of string): string;
begin
  var s1 := lst[0];
  var s2 := lst[1];
  var stack := new Stack<char>;
  var i := 1;
  var j := 1;
  while (i <= s1.Length) and (j <= s2.Length) do
  begin
    if s1[i] = '(' then
      stack.Push(s1[i])
    else if s1[i] = ')' then
    begin
      if stack.Count = 0 then
        break;
      stack.Pop;
    end;
    i += 1;
    if (i > s1.Length) and (j <= s2.Length) then
    begin
      if s2[j] = '(' then
        stack.Push(s2[j])
      else if s2[j] = ')' then
      begin
        if stack.Count = 0 then
          break;
        stack.Pop;
      end;
      j += 1;
    end;
  end;
  if stack.Count <> 0 then
    Result := 'No'
  else
    Result := 'Yes';
end;


function Maximum(arr: array of integer; k: integer): array of integer;
begin
  if (k = 0) or (arr.Length = 0) then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := arr.ToArray;
  sorted.Sort;
  var maxHeap := new List<integer>;

  for var i := 0 to sorted.Length - 1 do
  begin
    maxHeap.Add(sorted[i]);
    if maxHeap.Count > k then
      maxHeap.RemoveAt(0);
  end;

  maxHeap.Reverse;
  Result := maxHeap.ToArray;
end;


