function Tri(n: integer): array of real;
begin
  var trib := new real[n + 1];
  trib[0] := 3;
  trib[1] := 1;
  trib[2] := 2;

  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      trib[i] := trib[i - 1] + trib[i - 2] + i div 2
    else
      trib[i] := trib[i - 1] + trib[i - 2] + trib[i - 3];
  end;

  Result := trib;
end;


