function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var negatives := lst.Where(x -> x < 0).ToArray;
  var positives := lst.Where(x -> x > 0).ToArray;

  if negatives.Length = 0 then
    Result := (0, positives.Length > 0 ? positives[0] : 0)
  else if positives.Length = 0 then
    Result := (negatives[negatives.Length - 1], 0)
  else
  begin
    var negMax := negatives.Max;
    var posMin := positives.Min;
    Result := (negMax, posMin);
  end;
end;


function CompareOne(a, b: object): object;
begin
  if a = b then
