    if (aType = 'real') and (bType = 'real') then
      Result := real(a) > real(b) ? a : b
    else if (aType = 'string') and (bType = 'string') then
      Result := string(a) > string(b) ? a : b
    else if (aType = 'integer') and (bType = 'integer') then
