function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var prevSpace := False;
  var prevPrevSpace := False;

  for var i := 1 to text.Length do
  begin
    var ch := text[i];

    if ch = ' ' then
    begin
      if not prevSpace then
        sb.Append('_');

      prevSpace := True;
      prevPrevSpace := False;
    end
    else
    begin
      sb.Append(ch);
      prevSpace := False;
      prevPrevSpace := False;
    end;

    if (i > 1) and (i < text.Length) and (text[i] = ' ') and (text[i - 1] = ' ') then
    begin
      sb.Append('-');
      prevPrevSpace := True;
    end;
  end;

  Result := sb.ToString;
end;


