function Simplify(x, n: string): boolean;
begin
  var xNum := StrToInt(x.Substring(0, x.IndexOf('/')));
  var xDenom := StrToInt(x.Substring(x.IndexOf('/') + 1));
  var nNum := StrToInt(n.Substring(0, n.IndexOf('/')));
  var nDenom := StrToInt(n.Substring(n.IndexOf('/') + 1));

  var num := xNum * nNum;
  var denom := xDenom * nDenom;

  Result := (num mod denom) = 0;
end;


function OrderByPoints(nums: array of integer): array of integer;
begin
  var numsCopy := nums.ToArray;
  var sumDigits := new List<(integer, integer)>;

  for var i := 0 to nums.Length - 1 do
    sumDigits.Add((i, nums[i].Abs.ToString.Sum(ch -> StrToInt(ch.ToString)).Sum));

  sumDigits.Sort((x, y) -> 
  begin
    if x[1] <> y[1] then
      Result := y[1].CompareTo(x[1])
    else
      Result := x[0].CompareTo(y[0]);
  end);

  var res := new List<integer>;
  foreach var (index, _) in sumDigits do
    res.Add(numsCopy[index]);

  Result := res.ToArray;
end;


