function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var stack := new Stack<integer>;
  foreach var x in operand do
    if op.Contains(x) then
    begin
      var y := stack.Pop;
      var z := stack.Pop;
      case x of
        '+': stack.Push(y + z);
        '-': stack.Push(y - z);
        '*': stack.Push(y * z);
        '//': stack.Push(y div z);
        '**': stack.Push(y ** z);
      end;
    end
    else
      stack.Push(x);
  Result := stack.Pop;
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  foreach var ch in s do
    if ch.IsLetter(ch) then
      letters.Add(ch);

  if letters.Count = 0 then
  begin
    var chars := s.ToCharArray;
    &Array.Reverse(chars);
    Result := new string(chars);
    exit;
  end;

  var chars := s.ToCharArray;
  for var i := 0 to chars.Length - 1 do
  begin
    if chars[i].IsLetter(chars[i]) then
      chars[i] := chars[i].ToUpper
    else
      chars[i] := chars[i].ToLower;
  end;

  Result := new string(chars);
end;


function StringToMd5(text: string): string;
